def monitor_connections(host: str, interval_s: int) -> list[dict]:
    connections = []
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.bind((host, 0))  # 0 = slumpmässig port
        s.listen()
        s.settimeout(interval_s)
        try:
            while True:
                try:
                    conn, addr = s.accept()
                    connections.append({
                        "timestamp": datetime.now().isoformat(),
                        "source": addr
                    })
                    conn.close()
                except socket.timeout:
                    break
        except KeyboardInterrupt:
            pass
    return connections
