    recommendations = {
        "Port": "Ändra från standardport 22 till en icke-standardport",
        "Protocol": "Använd endast Protocol 2",
        "PermitRootLogin": "Sätt till 'no'",
        "PasswordAuthentication": "Sätt till 'no' om möjligt",
        "X11Forwarding": "Sätt till 'no' om ej behövs",
        "MaxAuthTries": "Sätt till 3 eller lägre",
        "LoginGraceTime": "Sätt till 60 eller lägre"
    }

    try:
        with open(config_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                key, value = re.split(r'\s+', line, 1)
                if key in recommendations:
                    del recommendations[key]
    except FileNotFoundError:
        pass

    return {"rekommendationer": recommendations}
